"""Plain-code steps: deterministic, testable, free to run."""
import re
from decimal import Decimal

# Stand-ins for the ERP. In real work these come from a database or API.
OPEN_POS = {"PO-1001": Decimal("59000.00"), "PO-1002": Decimal("12000.00")}
SEEN_INVOICES: set[tuple[str, str]] = set()

# Indian GSTIN: 2-digit state, 10-char PAN, entity code, 'Z', checksum.
GSTIN_RE = re.compile(r"^\d{2}[A-Z]{5}\d{4}[A-Z][1-9A-Z]Z[0-9A-Z]$")


def to_money(value: float) -> Decimal:
    return Decimal(str(value)).quantize(Decimal("0.01"))


def validate(fields) -> list[str]:
    """Return a list of problems. Empty list means the invoice is clean."""
    problems = []
    if not fields.gstin or not GSTIN_RE.match(fields.gstin):
        problems.append("invalid_gstin")
    subtotal, gst, total = map(to_money, (fields.subtotal, fields.gst_amount, fields.total))
    if abs(subtotal + gst - total) > Decimal("1.00"):  # allow rupee rounding
        problems.append("totals_do_not_add_up")
    key = (fields.vendor_name.lower(), fields.invoice_number)
    if key in SEEN_INVOICES:
        problems.append("duplicate_invoice")
    SEEN_INVOICES.add(key)
    return problems


def match_po(fields) -> str:
    if not fields.po_number or fields.po_number not in OPEN_POS:
        return "no_po"
    if to_money(fields.total) > OPEN_POS[fields.po_number]:
        return "amount_exceeds_po"
    return "matched"


def route(fields, problems: list[str], po_status: str, limit: int) -> str:
    """The 'decide' step, kept as rules so finance can read and audit it."""
    if "duplicate_invoice" in problems:
        return "reject"
    if problems or po_status != "matched":
        return "human_review"          # exception: a person must look
    if to_money(fields.total) > Decimal(limit):
        return "human_review"          # high value: a person must approve
    return "auto_post"

"""LLM steps: classify, extract, draft. Each returns structured output."""
from typing import Literal

from langchain.chat_models import init_chat_model
from pydantic import BaseModel, Field

# temperature=0: we want the same answer for the same document.
model = init_chat_model("openai:gpt-4.1-mini", temperature=0)


class DocType(BaseModel):
    label: Literal["invoice", "credit_note", "quote", "other"]
    confidence: float = Field(ge=0, le=1, description="How sure you are, 0 to 1")


class InvoiceFields(BaseModel):
    vendor_name: str
    gstin: str | None = Field(description="15-character GSTIN of the vendor")
    invoice_number: str
    po_number: str | None = Field(description="Purchase order number, e.g. PO-1001")
    subtotal: float = Field(description="Amount before GST in INR")
    gst_amount: float = Field(description="Total of CGST+SGST or IGST in INR")
    total: float = Field(description="Grand total in INR")


class QueryEmail(BaseModel):
    subject: str
    body: str


def classify(text: str) -> DocType:
    # LLM step type: classify -> one label from a fixed list.
    return model.with_structured_output(DocType).invoke(
        f"Classify this business document.\n\n{text}"
    )


def extract(text: str) -> InvoiceFields:
    # LLM step type: extract -> typed fields. Plain code validates them next.
    return model.with_structured_output(InvoiceFields).invoke(
        "Extract the invoice fields. Use null if a field is missing. "
        f"Do not guess numbers.\n\n{text}"
    )


def draft_query(fields: InvoiceFields, problems: list[str]) -> QueryEmail:
    # LLM step type: draft -> text for a human to review, never auto-sent.
    return model.with_structured_output(QueryEmail).invoke(
        f"Write a short, polite email to {fields.vendor_name} about invoice "
        f"{fields.invoice_number}. Issues found: {', '.join(problems)}. "
        "Ask them to send a corrected invoice."
    )

