"""Pydantic schema used for structured output and validation."""
from datetime import date
from typing import Literal

from pydantic import BaseModel, Field, field_validator

# GSTIN format: 2-digit state code, PAN (5 letters, 4 digits, 1 letter),
# entity number, the letter Z, and a check character. Format check only.
GSTIN_PATTERN = r"^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$"


class Invoice(BaseModel):
    """Key fields from one Indian GST invoice."""

    # Classification: a fixed set of labels the model must choose from
    document_type: Literal["invoice", "credit_note", "other"] = Field(
        description="Type of document. Use credit_note for credit or debit notes."
    )
    # Extraction: values copied from the document text
    vendor: str = Field(
        min_length=2, description="Legal name of the seller who issued the document"
    )
    amount: float = Field(
        gt=0, description="Grand total payable in INR including GST, as a number"
    )
    due_date: date = Field(description="Payment due date in YYYY-MM-DD format")
    gstin: str = Field(
        pattern=GSTIN_PATTERN, description="Seller's 15-character GSTIN"
    )

    # Runs before the pattern check: removes spaces and uppercases the GSTIN
    @field_validator("gstin", mode="before")
    @classmethod
    def normalise_gstin(cls, value: object) -> str:
        return str(value).replace(" ", "").upper()

    # Keep money to 2 decimal places
    @field_validator("amount")
    @classmethod
    def round_amount(cls, value: float) -> float:
        return round(value, 2)

