    d = interrupt({"original": state["email"], "draft": state["draft"]})
    if d["type"] == "reject":
        return Command(goto=END)
    if d["type"] == "edit":
        return Command(update={"draft": d["draft"]}, goto="send")
    return Command(goto="send")

