import json, os
from typing import Literal, TypedDict
from langgraph.graph import StateGraph, START, END
from langgraph.types import interrupt, Command

class State(TypedDict, total=False):
    email: dict      # {from, subject, body}
    category: str    # respond | ignore
    draft: dict      # {to, subject, body}
    decision: str    # approve | edit | reject
    sent: bool

def triage(state: State):
    text = (state["email"]["subject"] + " " + state["email"]["body"]).lower()
    ignore = any(w in text for w in ("unsubscribe", "newsletter"))
    return {"category": "ignore" if ignore else "respond"}

def route(state: State) -> Literal["draft_reply", "__end__"]:
    return "draft_reply" if state["category"] == "respond" else END

def draft_reply(state: State):
    e = state["email"]
    body = (f"Hi,\n\nThanks for your message about '{e['subject']}'. "
            "We will reply within one working day.\n\nRegards,\nSupport")
    if os.getenv("OPENAI_API_KEY"):  # optional LLM draft
        from langchain.chat_models import init_chat_model
        model = init_chat_model(os.getenv("MODEL", "openai:gpt-4o-mini"))
        body = model.invoke(f"Write a short, polite reply to:\n{e['body']}").content
    return {"draft": {"to": e["from"], "subject": "Re: " + e["subject"], "body": body}}

def human_review(state: State) -> Command[Literal["send_email", "__end__"]]:
    # On resume this node re-runs from the top, so nothing before
    # interrupt() may have side effects.
    decision = interrupt({
        "type": "email_approval",
        "original": state["email"],
        "category": state["category"],
        "draft": state["draft"],
        "allowed_decisions": ["approve", "edit", "reject"],
    })  # the value passed in Command(resume=...) is returned here
    if decision["type"] == "approve":
        return Command(goto="send_email", update={"decision": "approve"})
    if decision["type"] == "edit":
        edited = {**state["draft"], **decision["draft"]}  # reviewer's fields win
        return Command(goto="send_email", update={"draft": edited, "decision": "edit"})
    return Command(goto=END, update={"decision": "reject", "sent": False})

def send_email(state: State):
    # Only reachable through human_review: no email leaves without approval.
    with open(os.getenv("OUTBOX_PATH", "outbox.jsonl"), "a") as f:
        f.write(json.dumps(state["draft"]) + "\n")
    return {"sent": True}

def build_graph(checkpointer=None):
    b = StateGraph(State)
    for name, fn in [("triage", triage), ("draft_reply", draft_reply),
                     ("human_review", human_review), ("send_email", send_email)]:
        b.add_node(name, fn)
    b.add_edge(START, "triage")
    b.add_conditional_edges("triage", route)
    b.add_edge("draft_reply", "human_review")
    b.add_edge("send_email", END)
    return b.compile(checkpointer=checkpointer)  # pausing needs a checkpointer

# For langgraph dev / Agent Server: the server adds persistence itself.
graph = build_graph()

