    """Send an email to a customer."""
    with open(os.getenv("OUTBOX_PATH", "outbox.jsonl"), "a") as f:
        f.write(json.dumps({"to": to, "subject": subject, "body": body}) + "\n")
    return f"Email sent to {to}"

