        model=os.getenv("MODEL", "openai:gpt-4o-mini"),
        tools=[send_email],
        system_prompt="You are a support triage assistant. Reply to customers with send_email.",
        middleware=[HumanInTheLoopMiddleware(
            # Sensitive tool: pause before every call
            interrupt_on={"send_email": {"allowed_decisions": ["approve", "edit", "reject"]}},
        )],
        checkpointer=checkpointer,  # outermost agent only, in multi-agent setups
    )

