    config = {"configurable": {"thread_id": "hitl-demo-1"}}
    msg = "Reply to priya@acme.in: her duplicate charge on invoice 4471 will be refunded."
    result = local.invoke({"messages": [{"role": "user", "content": msg}]}, config)
    while "__interrupt__" in result:
        req = result["__interrupt__"][0].value["action_requests"][0]
        print("Tool:", req["name"], "\nArgs:", json.dumps(req["args"], indent=2))
        choice = input("approve / edit / reject > ").strip().lower()
        if choice == "edit":
            args = {**req["args"], "body": input("New body: ")}
            decision = {"type": "edit", "edited_action": {"name": req["name"], "args": args}}
        elif choice == "approve":
            decision = {"type": "approve"}
        else:
            decision = {"type": "reject", "message": "Reviewer rejected this email."}
        # One decision per pending action request, same thread_id
        result = local.invoke(Command(resume={"decisions": [decision]}), config)
    print(result["messages"][-1].content)

