"""A small local ticketing API. It behaves like Jira, Zendesk or Freshdesk
when they honour an Idempotency-Key header or an external-id lookup."""
import os
import uuid

from fastapi import FastAPI, Header, HTTPException
from pydantic import BaseModel

app = FastAPI(title="tickets")
TICKETS: dict[str, dict] = {}   # ticket_id -> ticket
BY_KEY: dict[str, str] = {}     # idempotency key -> ticket_id
TOKEN = os.environ.get("TICKET_API_TOKEN", "dev-token")


class TicketIn(BaseModel):
    source_row_id: str
    title: str
    description: str
    priority: str = "medium"


@app.post("/tickets")
def create_ticket(body: TicketIn, idempotency_key: str = Header(...), authorization: str = Header(...)):
    if authorization != f"Bearer {TOKEN}":
        raise HTTPException(status_code=401, detail="bad token")
    # Same key seen before: return the original ticket and do not create another
    if idempotency_key in BY_KEY:
        return {**TICKETS[BY_KEY[idempotency_key]], "created": False}
    ticket_id = f"TCK-{uuid.uuid4().hex[:6].upper()}"
    TICKETS[ticket_id] = {"id": ticket_id, **body.model_dump()}
    BY_KEY[idempotency_key] = ticket_id
    return {**TICKETS[ticket_id], "created": True}


@app.get("/tickets")
def list_tickets():
    return list(TICKETS.values())

