"""Paste the body of perform_eval into a LangSmith online *code* evaluator.

In the UI: project invoice-agent-prod -> New -> Online evaluator -> Code.
The returned dict key becomes the feedback key on the run.
"""
import re

# Expected answer shape from the system prompt: 'INV-101 | paid | Rs 48500'
FORMAT = re.compile(r"INV-\d+\s*\|\s*\w+\s*\|\s*Rs\s*[\d,]+")


def perform_eval(run, example):
    outputs = run.get("outputs") or {}
    messages = outputs.get("messages") or []
    if not messages:
        # No output at all (e.g. errored run): score 0
        return {"invoice_quality": 0}
    last = messages[-1]
    # Serialised messages may be dicts with 'content' or nested 'kwargs'
    content = last.get("content") or last.get("kwargs", {}).get("content", "")
    if isinstance(content, list):  # content blocks -> join text parts
        content = " ".join(b.get("text", "") for b in content if isinstance(b, dict))
    ok = bool(FORMAT.search(str(content)))
    return {"invoice_quality": 1 if ok else 0}


if __name__ == "__main__":
    # Local sanity check before pasting into LangSmith
    good = {"outputs": {"messages": [{"content": "INV-101 | paid | Rs 48500"}]}}
    bad = {"outputs": {"messages": [{"content": "Why did the accountant..."}]}}
    print(perform_eval(good, None), perform_eval(bad, None))

