import json, os, requests

URL = "http://localhost:7860/api/v1/run/" + os.environ["FLOW_ID"]
HEADERS = {"x-api-key": os.environ["LANGFLOW_API_KEY"]}
FIELDS = ["invoice_number", "vendor", "invoice_date", "currency", "total"]

def run_flow(text: str) -> dict:
    body = {"input_value": text, "input_type": "chat", "output_type": "chat"}
    r = requests.post(URL, json=body, headers=HEADERS, timeout=120)
    r.raise_for_status()
    msg = r.json()["outputs"][0]["outputs"][0]["results"]["message"]["text"]
    return json.loads(msg)

coded = json.load(open("coded_results.json"))  # {filename: {field: value}}
mismatches = 0
for name, expected in coded.items():
    got = run_flow(open(f"invoices/{name}.txt").read())
    for f in FIELDS:
        if str(got.get(f)).strip() != str(expected.get(f)).strip():
            mismatches += 1
            print(f"{name}.{f}: flow={got.get(f)!r} code={expected.get(f)!r}")

print("agree on all 10" if mismatches == 0 else f"{mismatches} field mismatches")

