"""Invoice agent: match invoices to POs, pay only after human approval."""
from langchain.agents import create_agent
from langchain.agents.middleware import (
    HumanInTheLoopMiddleware,
    ModelCallLimitMiddleware,
    PIIMiddleware,
    ToolRetryMiddleware,
)
from langchain.tools import tool

# Demo data. In real work, replace these with your ERP or accounting API.
INVOICES = {
    "INV-101": {"vendor": "Sharma Supplies", "amount": 48000, "po": "PO-77"},
    "INV-102": {"vendor": "Rao Logistics", "amount": 125000, "po": "PO-80"},
}
POS = {"PO-77": 48000, "PO-80": 110000}


@tool
def list_pending_invoices() -> list[str]:
    """Return the IDs of invoices waiting to be processed."""
    return list(INVOICES)


@tool
def match_to_po(invoice_id: str) -> dict:
    """Compare the invoice amount with its purchase order amount."""
    inv = INVOICES[invoice_id]
    po_amount = POS.get(inv["po"])
    return {**inv, "po_amount": po_amount, "matches": po_amount == inv["amount"]}


@tool
def post_payment(invoice_id: str, amount: int, note: str) -> str:
    """Schedule a payment. Needs human approval (see middleware)."""
    return f"Payment of INR {amount} scheduled for {invoice_id}: {note}"


SYSTEM_PROMPT = (
    "You process supplier invoices. For each pending invoice call match_to_po. "
    "If it matches, call post_payment. If it does not match, still call post_payment "
    "with a note that explains the mismatch, so a human can decide. "
    "End with a one-line summary for each invoice."
)

# No checkpointer here: the Agent Server adds persistence automatically.
agent = create_agent(
    model="openai:gpt-4.1-mini",
    tools=[list_pending_invoices, match_to_po, post_payment],
    system_prompt=SYSTEM_PROMPT,
    middleware=[
        PIIMiddleware("email", strategy="redact", apply_to_input=True),  # no emails reach the model
        ToolRetryMiddleware(max_retries=2),       # retry flaky tool calls (protects the error budget)
        ModelCallLimitMiddleware(run_limit=10),   # hard cap on model calls (protects the cost budget)
        HumanInTheLoopMiddleware(                 # pause before any money moves
            interrupt_on={
                "post_payment": {"allowed_decisions": ["approve", "edit", "reject"]}
            }
        ),
    ],
)

